import sys
from itertools import combinations

def landau_criterion(d):
    n = len(d)
    for k in range(1, n):
        if sum(d[:k]) < k * (k - 1) / 2 + sum(d[k:n]):
            return False
    return sum(d) == n * (n - 1) / 2

def construct_tournament(scores):
    scores.sort()
    n = len(scores)
    while True:
        if landau_criterion([i for i in range(n) if i not in scores] + scores):
            break
        n += 1
    d = [0] * n
    for s in scores:
        d[s] += 1
    matrix = [[0] * n for _ in range(n)]
    available = [i for i in range(n) if d[i] > 0]
    for i in range(n):
        needed = d[i]
        for j in available:
            if i != j and matrix[i][j] == 0:
                matrix[i][j] = 1
                d[j] -= 1
                if d[j] == 0:
                    available.remove(j)
                needed -= 1
                if needed == 0:
                    break
    return n, [''.join(map(str, row)) for row in matrix]

def main():
    input = sys.stdin.read().split()
    m = int(input[0])
    S = list(map(int, input[1:]))
    result = construct_tournament(S)
    if result == '=(':
        print(result)
    else:
        n, matrix = result
        print(n)
        for row in matrix:
            print(row)

